SELECT "investor_name" AS "investor_name", "investor_gp_id" AS "investor_id", "tranche_name" AS "tranche_name", "order_demand_qty" AS "order_demand_qty", "demand_as_submitted" AS "demand_as_submitted", "demand_unit" AS "demand_unit", "order_allocation" AS "order_allocation", COUNT("order_id") AS "row_count" FROM "bds_dg_oraas"."dgstream"."vw_order_detail" WHERE "product" = __P_f0__ AND "transaction_id" = __P_f1__ AND UPPER("investor_name") LIKE UPPER(__P_f2__) GROUP BY "investor_name", "investor_gp_id", "tranche_name", "order_demand_qty", "demand_as_submitted", "demand_unit", "order_allocation" LIMIT 50
